<?php $title='Contact Us';require 'includes/header.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO contact_messages(name,email,phone,subject,message) VALUES(?,?,?,?,?)")->execute([trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['subject']),trim($_POST['message'])]);$msg='Message sent successfully.';}?><section class="page-head"><div class="container"><h1>Contact Us</h1><p>We are ready to help with your product requirements.</p></div></section><div class="container py-5"><div class="row g-5"><div class="col-lg-5"><h3>Get in touch</h3><p><?=e($settings['address']??'Your Business Address')?></p><p><i class="bi bi-telephone"></i> <?=e($settings['phone']??'+91 XXXXX XXXXX')?></p><p><i class="bi bi-envelope"></i> <?=e($settings['email']??'info@example.com')?></p></div><div class="col-lg-7"><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><form method="post" class="card border-0 shadow-sm p-4 rounded-4"><div class="row g-3"><div class="col-md-6"><input required name="name" class="form-control" placeholder="Name"></div><div class="col-md-6"><input required type="email" name="email" class="form-control" placeholder="Email"></div><div class="col-md-6"><input name="phone" class="form-control" placeholder="Phone"></div><div class="col-md-6"><input name="subject" class="form-control" placeholder="Subject"></div><div class="col-12"><textarea required name="message" rows="5" class="form-control" placeholder="Message"></textarea></div><div class="col-12"><button class="btn btn-primary">Send Message</button></div></div></form></div></div></div><?php require 'includes/footer.php';?>